-- A-Level Business Flashcards — Edexcel (9BS0)
-- Generated for the RAG Learning study app from the specification and question banks.
-- One INSERT per topic. card_order restarts at 1 within each topic.
--
-- SAFE TO RE-RUN: the DELETE below clears any previous Business Studies/Edexcel/alevel
-- rows first, so running this file twice does not duplicate cards.
--
-- WHAT IS HERE: 20 topics x 8 cards = 160. All four themes are loaded.
-- Every 9BS0 topic is compulsory (no optional routes), so every student
-- sees all 20 topics.
--
-- TOPIC IDS match topics-config.js and the question banks exactly. They are
-- the join key, so do not renumber them here without renumbering everywhere.

-- ---------------------------------------------------------------
-- Schema: add 'level' column if not present (idempotent).
-- Every row below is level = 'alevel'.
-- ---------------------------------------------------------------
ALTER TABLE flashcards ADD COLUMN IF NOT EXISTS level TEXT DEFAULT 'alevel'
  CHECK (level IN ('gcse','as','alevel'));

-- ---------------------------------------------------------------
-- Clear any existing Business Studies/Edexcel A-Level cards so this file is
-- re-runnable. Note this touches ONLY exam_board = 'Edexcel' at level
-- 'alevel'; any other board or level of Business Studies is untouched.
-- ---------------------------------------------------------------
DELETE FROM flashcards
 WHERE subject = 'Business Studies' AND exam_board = 'Edexcel' AND level = 'alevel';


